const req = indexedDB.open('shop', 1);
req.onupgradeneeded = () => {
  req.result.createObjectStore('drafts', {keyPath:'id'});
};
req.onsuccess = () => {
  const tx = req.result.transaction('drafts','readwrite');
  tx.objectStore('drafts').put({id:1, text:'Tea'});
  tx.oncomplete = () => console.log('Saved');
};
